ClipboardPage cp_top = tools.getPrimaryPage().getTopLevelPage();
if(cp_top.getIfPresent("pzPageToDisplay") != null){
	tools.putParamValue("currReportPage",cp_top.getString("pzPageToDisplay")+".pyReportDefinition");
	tools.putParamValue("parentReportPage",cp_top.getString("pzPageToDisplay")+".pyReportDefinition");
//	tools.putParamValue("parentReportPage",cp_top.getName()+".pyReportDefinition");
}else{
  // If currently bulk validating, give the top level page a name
  String topName = cp_top.getName();
  if(cp_top.getName().isEmpty()) {
    cp_top.rename("RH_1");
  }
	tools.putParamValue("currReportPage",cp_top.getName());
	tools.putParamValue("parentReportPage",cp_top.getName());
}

ClipboardProperty joinsInfo = myStepPage.getProperty(".pyJoinInfo");
for(Iterator it = joinsInfo.iterator(); it.hasNext(); ) {
    ClipboardProperty cp = (ClipboardProperty) it.next();
    ClipboardPage joinsInfoPage = (cp).getPageValue();
    if(!bIndexName.equals(joinsInfoPage.getString(".pyPrefix"))) {
        ClipboardProperty filters = joinsInfoPage.getProperty(".pyFilters.pyFilter");
        for(Iterator filterIt = filters.iterator(); filterIt.hasNext(); ) {
            ClipboardProperty filterProp = (ClipboardProperty) filterIt.next();
            ClipboardPage filterPage = (filterProp).getPageValue();
            String filterValue = filterPage.getString("pyFilterValue");
            String filterName = filterPage.getString("pyFilterName");
            if(filterValue.startsWith(bIndexName + ".") || filterName.startsWith(bIndexName + ".")) {
                bFoundIndexUsage = true;
                return true;
            }
        }
    }
}

ClipboardProperty subreportInfo = myStepPage.getProperty(".pySubReportInfo");
for(Iterator it = subreportInfo.iterator(); it.hasNext(); ) {
    ClipboardProperty subreportPage = (ClipboardProperty) it.next();
    ClipboardProperty filters = subreportPage.getProperty(".pyFilters.pyFilter");
    for(Iterator filterIt = filters.iterator(); filterIt.hasNext(); ) {
        ClipboardProperty filterProp = (ClipboardProperty) filterIt.next();
        ClipboardPage filterPage = (filterProp).getPageValue();
        String filterValue = filterPage.getString("pyFilterValue");
        String filterName = filterPage.getString("pyFilterName");
        if(filterValue.startsWith(bIndexName + ".") || filterName.startsWith(bIndexName + ".")) {
            bFoundIndexUsage = true;
            return true;
        }
    }
}
